'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useState } from 'react'
import Button from '@mui/material/Button'
import Grid from '@mui/material/Grid'
import { useTranslations } from 'next-intl'
import { ApiError } from '@/lib/api/client'
import { useConstraints } from '@/lib/reference'
import { Modal } from '@/components/modal'
import { SelectField, TextField } from '@/components/form-fields'
import { useToast } from '@/components/toast-provider'
import { useOptions } from '../shared'
import { useSaveProduct } from './api'
import type { Product, ProductInput } from './types'

interface FormState {
  sku: string
  name: string
  price: string
  countryCode: string
}

export function ProductFormModal({ row, onClose }: { row: Product | null; onClose: () => void }) {
  const t = useTranslations('shop')
  const tCommon = useTranslations('common')
  const field = useConstraints('shopProduct')
  const toast = useToast()
  const save = useSaveProduct()
  const countryCodeOptions = useOptions('/api/shop/countries', 'code', 'name')
  const [form, setForm] = useState<FormState>({
    sku: row?.sku ?? '',
    name: row?.name ?? '',
    price: row?.price != null ? String(row?.price) : '',
    countryCode: row?.countryCode != null ? String(row?.countryCode) : '',
  })
  const errors = save.error instanceof ApiError ? save.error.fieldErrors : {}
  const set =
    <K extends keyof FormState>(key: K) =>
    (value: FormState[K]) =>
      setForm(f => ({ ...f, [key]: value }))

  const submit = () => {
    const input: ProductInput = {
      sku: form.sku || null,
      name: form.name || null,
      price: form.price === '' ? null : Number(form.price),
      countryCode: form.countryCode === '' ? null : form.countryCode,
      tagIds: row?.tagIds ?? [],
    }
    save.mutate(
      { id: row?.id, input },
      {
        onSuccess: () => {
          toast.success(row ? tCommon('saved') : tCommon('created'))
          onClose()
        },
        onError: error => {
          if (!(error instanceof ApiError) || Object.keys(error.fieldErrors).length === 0) {
            toast.error(error instanceof ApiError ? error.message : tCommon('unknownError'))
          }
        },
      }
    )
  }

  return (
    <Modal
      open
      title={row ? t('product.edit') : t('product.new')}
      onClose={onClose}
      busy={save.isPending}
      onSubmit={submit}
      footer={
        <>
          <Button variant="outlined" color="inherit" onClick={onClose} disabled={save.isPending}>
            {tCommon('cancel')}
          </Button>
          <Button type="submit" variant="contained" disabled={save.isPending}>
            {save.isPending ? tCommon('saving') : tCommon('save')}
          </Button>
        </>
      }
    >
      <Grid container spacing={2}>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('product.fields.sku')}
            value={form.sku}
            onChange={set('sku')}
            {...field('sku')}
            error={errors.sku}
          />
        </Grid>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('product.fields.name')}
            value={form.name}
            onChange={set('name')}
            {...field('name')}
            error={errors.name}
          />
        </Grid>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('product.fields.price')}
            type="number"
            value={form.price}
            onChange={set('price')}
            {...field('price')}
            error={errors.price}
          />
        </Grid>
        <Grid size={{ xs: 12, md: 6 }}>
          <SelectField
            label={t('product.fields.countryCode')}
            value={form.countryCode}
            onChange={set('countryCode')}
            required={field('countryCode').required}
            error={errors.countryCode}
          >
            <option value="">–</option>
            {(countryCodeOptions.data ?? []).map(o => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </SelectField>
        </Grid>
      </Grid>
    </Modal>
  )
}
